import subprocess
from contextlib import contextmanager

@contextmanager
def managed_subprocess(args):
    """上下文管理器，自动管理子进程的启动、等待与终止

    Args:
        args (list): 子进程启动参数列表

    Yields:
        subprocess.Popen: 子进程对象
    """
    proc = None
    try:
        proc = subprocess.Popen(args)
        yield proc
    finally:
        if proc:
            if proc.poll() is None:
                proc.terminate()
                try:
                    proc.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    proc.kill()

def start_process():
    """启动并管理Python服务器子进程"""
    with managed_subprocess(["python", "server.py"]) as proc:
        proc.wait()
